    size: "1920×1080",
    html: "<!doctype html>\r\n<html lang=\"zh-CN\" data-composition-variables='[{\"id\":\"title\",\"type\":\"string\",\"label\":\"标题\",\"default\":\"累计用户数\"},{\"id\":\"targetValue\",\"type\":\"number\",\"label\":\"目标数值\",\"default\":1285000},{\"id\":\"prefix\",\"type\":\"string\",\"label\":\"前缀\",\"default\":\"\"},{\"id\":\"suffix\",\"type\":\"string\",\"label\":\"后缀\",\"default\":\"+\"},{\"id\":\"note\",\"type\":\"string\",\"label\":\"补充说明\",\"default\":\"突破百万里程碑，持续增长中\"},{\"id\":\"accent\",\"type\":\"color\",\"label\":\"强调色\",\"default\":\"#FF5A36\"},{\"id\":\"background\",\"type\":\"color\",\"label\":\"背景色\",\"default\":\"#12100E\"},{\"id\":\"foreground\",\"type\":\"color\",\"label\":\"文字色\",\"default\":\"#F4EFE7\"},{\"id\":\"exportMode\",\"type\":\"enum\",\"label\":\"导出模式\",\"default\":\"transparent\",\"hidden\":true,\"options\":[{\"value\":\"transparent\",\"label\":\"透明背景\"},{\"value\":\"mp4\",\"label\":\"剪映 MP4 深色底\"}]}]'>\r\n  <head>\r\n    <meta charset=\"UTF-8\" /><meta name=\"viewport\" content=\"width=1920, height=1080\" />\r\n    <script src=\"/vendor/gsap.min.js\"></script>\r\n    <style>\r\n      * { box-sizing: border-box; }\r\n      html, body { margin: 0; width: 1920px; height: 1080px; overflow: hidden; background: transparent; }\r\n      html[data-export-mode=\"mp4\"] body, html[data-export-mode=\"mp4\"] #root { background: var(--background, #12100e) !important; }\r\n      body { font-family: \"IBM Plex Mono\", monospace; }\r\n      #root { position: relative; width: 1920px; height: 1080px; overflow: hidden; background: transparent; color: var(--foreground, #f4efe7); }\r\n      .scene { position: absolute; inset: 0; width: 100%; height: 100%; padding: 82px 108px 78px; overflow: hidden; }\r\n      .counter-panel { position: relative; width: 100%; height: 100%; display: grid; grid-template-rows: auto 1fr auto; }\r\n      .counter-panel::before { content: \"\"; position: absolute; left: 0; right: 0; top: 0; height: 8px; background: linear-gradient(90deg,var(--accent) 0 38%,color-mix(in srgb,var(--accent) 18%,transparent) 38%); }\r\n      .title { align-self: start; padding-top: 58px; font-family: sans-serif; font-size: 82px; font-weight: 900; letter-spacing: -0.05em; color: var(--foreground); }\r\n      .counter-wrap { align-self: center; display: flex; align-items: flex-end; gap: 28px; min-width: 0; }\r\n      .value { font-size: 292px; font-weight: 900; line-height: 0.8; letter-spacing: -0.075em; font-variant-numeric: tabular-nums; color: var(--accent); white-space: nowrap; }\r\n      .suffix { font-size: 104px; font-weight: 800; line-height: 1; color: var(--accent); padding-bottom: 22px; }\r\n      .note { justify-self: end; width: 58%; padding: 32px 0 0 44px; border-top: 2px solid rgba(244,239,231,.24); border-left: 2px solid rgba(244,239,231,.24); font-family: sans-serif; font-size: 42px; font-weight: 700; line-height: 1.42; color: rgba(244,239,231,.82); }\r\n    </style>\r\n  </head>\r\n  <body>\r\n    <div id=\"root\" data-composition-id=\"main\" data-start=\"0\" data-duration=\"5\" data-width=\"1920\" data-height=\"1080\">\r\n      <section id=\"scene\" class=\"scene clip\" data-start=\"0\" data-duration=\"5\" data-track-index=\"1\">\r\n        <div class=\"counter-panel\">\r\n          <div class=\"title\" id=\"title\"></div>\r\n          <div class=\"counter-wrap\">\r\n            <span class=\"value\" id=\"value\">0</span>\r\n            <span class=\"suffix\" id=\"suffix\"></span>\r\n          </div>\r\n          <div class=\"note\" id=\"note\"></div>\r\n        </div>\r\n      </section>\r\n    </div>\r\n    <script>\r\n      const fallback = { title: \"累计用户数\", targetValue: 1285000, prefix: \"\", suffix: \"+\", note: \"突破百万里程碑，持续增长中\", accent: \"#FF5A36\", background: \"#12100E\", foreground: \"#F4EFE7\", exportMode: \"transparent\" };\r\n      const v = window.__hyperframes?.getVariables ? window.__hyperframes.getVariables() : fallback;\r\n      document.documentElement.dataset.exportMode = v.exportMode || \"transparent\";\r\n      document.documentElement.style.setProperty(\"--accent\", v.accent);\r\n      document.documentElement.style.setProperty(\"--background\", v.background);\r\n      document.documentElement.style.setProperty(\"--foreground\", v.foreground);\r\n      for (const [id, value] of [[\"title\", v.title], [\"suffix\", v.suffix], [\"note\", v.note]]) document.getElementById(id).textContent = value;\r\n\r\n      const targetValue = Number(v.targetValue) || 0;\r\n      const prefix = v.prefix || \"\";\r\n      const valueEl = document.getElementById(\"value\");\r\n      function formatNumber(n) { return n.toLocaleString(\"en-US\"); }\r\n\r\n      window.__timelines = window.__timelines || {};\r\n      const tl = gsap.timeline({ paused: true });\r\n      tl.fromTo(\".counter-panel\", { opacity: 0, y: 54 }, { opacity: 1, y: 0, duration: 0.65, ease: \"expo.out\" }, 0.1);\r\n      tl.fromTo(\".title\", { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.5, ease: \"power3.out\" }, 0.35);\r\n      const counterObj = { val: 0 };\r\n      tl.to(counterObj, { val: targetValue, duration: 2.5, ease: \"power2.out\", onUpdate: () => { valueEl.textContent = prefix + formatNumber(Math.round(counterObj.val)); } }, 0.55);\r\n      tl.fromTo(\".suffix\", { opacity: 0, x: 20 }, { opacity: 1, x: 0, duration: 0.5, ease: \"back.out(1.5)\" }, 2.2);\r\n      tl.fromTo(\".note\", { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.6, ease: \"power3.out\" }, 2.0);\r\n      tl.fromTo(\".value\", { scale: 1 }, { scale: 1.02, duration: 0.15, ease: \"power2.out\", yoyo: true, repeat: 1 }, 2.9);\r\n      tl.to(\".scene\", { opacity: 0, scale: 1.01, duration: 0.5, ease: \"power2.in\" }, 4.3);\r\n      window.__timelines.main = tl;\r\n    </script>\r\n  </body>\r\n</html>\r\n",
